import ast
import json
from collections import Counter
def task_func(file_pointer):
    data = json.load(file_pointer)
    counter = Counter()

    for entry in data:
        if isinstance(entry, str):
            d = ast.literal_eval(entry)
        else:
            d = entry

        if isinstance(d, dict):
            counter.update(d.keys())

    return counter
